%[text] %[text:anchor:H_E79E4298] ## Helper Functions
%[text] This function draws circles of specified `radius` around each element of `x1`. Input `spread` controls spread in the y direction and `n` is the sample size. A `seed` for the random number generator is specified for reproducibility.
function ShowPercentiles(seed,radius,spread,n)

% Generate normally distributed data
rng(seed)
x1 = randn(1,n);

% Plot circles with specified radius and spread
figure
t = 0:0.1:1'*2*pi;
hold on
cmap = colororder;
for i=1:length(x1)
    x = x1(i)+radius*cos(t);
    y = spread*rand+radius*sin(t);
    fill(x,y,cmap(1,:),'FaceAlpha',0.3)
end
hold off

% Plot the quantile lines
p = [0.025,0.16,0.25,0.5,0.75,0.84,0.975];
q = quantile(x1,p);
for i=[1 2 6 7]
    xline(q(i),'-',p(i),SeriesIndex="none");
end
for i=[3 5]
    xline(q(i),'-',p(i),"Color",cmap(1,:));
end
for i=[4]
    xline(q(i),'-',p(i),"Color",cmap(2,:));
end
axis equal
xlabel('X'),yticks([])
nstr = num2str(n);
title(['Percentiles of X ~ N(0, 1), n = ' nstr])

end
%[text] This function plots the histogram of the vector data input `x2,` over an existing plot. It labels the data with its mean `mu`, and standard deviation `sd`.
function ShowHistogram(mu,sd,x2)

hold on
str = sprintf('Mu = %d,SD = %d',mu,sd); % convert the parameters to strings
histogram(x2,'FaceAlpha',0.3,'DisplayName',str) % draw the histogram
legend('-DynamicLegend','Location','southoutside') % draw the legend
xlabel('X'),
ylabel('Frequency')
title('Histogram')
hold off

end
%[text] This function displays the mean `distMean` and median `distMed` as vertical lines overlaid on the histogram of the input vector `distribution`.
function ShowMeanMed(distribution,distMean,distMed)
histogram(distribution)             % draw the histogram
mean1str = num2str(round(distMean,2)); % create a string
med1str = num2str(round(distMed,2));   % create a string
xline(distMean,"-","mean = "+ mean1str,LineWidth=1.5,LabelVerticalAlignment="middle",SeriesIndex="none");
xline(distMed,"-","median = "+ med1str,LineWidth=1.5,SeriesIndex=2); 
drawnow
xlabel('X'),
ylabel('Frequency'),
title('Histogram, n = 1000')
end
